window.VD=window.VD||{};window.VD["audi/a8-d4"]={"a8-d4-acc-distance-setting-in-mmi":"<p><strong>Purpose</strong>: to change the distance of the Adaptive Cruise Control (ACC) on the menu in Audi MMI 3G.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>13 – Regulation dist</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>” .</p>\n<p><strong>5</strong> – Choose <em><strong>Channel 7</strong> </em>then set the value to <strong>1</strong></p>\n<p><em>Restart MMI (MENU + CAR 10 sec).</em></p>\n<p><em>For the cruise control menu, press CAR then driver assistance then Adaptive cruise control, you can choose “Distance” 4 distance selection modes</em>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7452-7b2530cd.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7166-a399eb74.webp\"/></figure>","a8-d4-activate-ambient-lighting":"<p><strong>Purpose</strong>: activates ambient lighting and its management via MMI.  </p>\n<p><strong>The hidden menu must be activated</strong> (see: <a href=\"https://www.vag-coding.fr/audi/a8-d4/a8-d4-activer-menu-cache-mmi-3gp/\" rel=\"noopener\" target=\"_blank\">Activating the MMI 3GP hidden menu</a>).  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <strong>Activate mood lighting</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong> “Long Coding Helper”</strong>.</p>\n<p><strong>5</strong> – Select <em>Byte <strong>16</strong>: </em><br/><em>Bit <strong>6</strong>: Tick “Interior/Ambiance Lighting Adaptation active”.</em></p>\n<p><strong>Line 2: Activate the MMI menu</strong></p>\n<p>Launch the Hidden Menu by pressing MENU + CAR (for 6s)</p>\n<p>car -&gt; carmenuoperation -&gt; interior light -&gt; select “5”.</p>\n<p>Press “Return</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/interior_light_hidden_menu_mmi3g-8680e758.webp\"/></figure>\n<p>  car -&gt; cardevicelist -&gt; interior light -&gt; check box</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/interior_light_hidden_menu_mmi3g1-9f0f03ff.webp\"/></figure>\n<p>  car -&gt; carbusassignment -&gt; Interior light -&gt; Select [CAN Komfort] 1/9</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_facelift_hidden_menu_car_carbusassignme-331aee89.webp\"/></figure>\n<p>Reboot the MMI by pressing MENU + Wheel + Top Right Button.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_reset-f3d493fd.webp\"/></figure>\n<p><strong>Line 3: Ambient lighting control from MMI</strong></p>\n<p><strong>How it works:</strong></p>\n<p><em>Ambient lighting</em><br/><em> – is permanently activated when the light control switch is in OFF position.</em><br/><em> – switches on/off automatically when the headlamp switch is in AUTO position.</em><br/><em> – will never light up to 100% (even when maximum lighting is selected).</em><br/><em> – lights up to 100% when doors are opened.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_facelift_setup_fussraumbeleuchtung-1639c23f.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_facelift_dimmung_fussraumbeleuchtung-2d9373cb.webp\"/></figure>","a8-d4-activate-battery-charge-status-in-mmi":"<p><strong>Purpose:</strong> Activates battery charge status in Audi MMI 3GP.  <br/></p>\n<p><em><strong>WARNING: </strong>You must have activated the Hidden Menu<a href=\"#/audi/a8-d4/a8-d4-activate-mmi-3gp-hidden-menu\">(Activate MMI 3GP hidden menu</a>).</em></p>\n<p><em>To launch the Hidden Menu press MENU + CAR (for 6s)</em></p>\n<p>car -&gt; carextdevicelist -&gt; battery -&gt; check box</p>\n<p>car -&gt; carmenuoperation -&gt; battery -&gt; select <strong>5</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Audi_MMI3g_PLUS_Hidden_Menue_battery-5a0d0626.webp\"/></figure>\n<p>Restart MMI</p>\n<p><em>Press SETUP + Wheel + Top Right Button.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/mmi3g_reset-cdd6298b.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Audi_MMI_3G_PLUS_batterie-69d82b4b.webp\"/></figure>","a8-d4-activate-dvd-playback-while-driving-vim":"<p><strong>Purpose</strong>: Allows you to remove the MMI protection and continue watching a DVD or video while driving (Video in Motion).   </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Step 1: Recovering the MMI 3GP serial number</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>5F-Computer-electr. </strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Advanced Ident -1A</strong>”.</p>\n<p>Retrieve serial number (if more than one, use the <strong>first</strong> one!)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a1_8x_mmi_plus_5f_seriennummer-PNG-12291981.webp\"/></figure>\n<p><strong>Step 2: Calculating the security code</strong></p>\n<p>Enter the serial number previously retrieved from the website (your choice, subject to availability):  </p>\n<p>–&gt; <a href=\"https://www.audienthusiasts.com/Articles_VIM.html\" rel=\"noopener\" target=\"_blank\">AUDIENTHUSIATS VIM</a></p>\n<p>–&gt; <a href=\"https://www.bestcarmods.com/vim/\" rel=\"noopener\" target=\"_blank\">BESTCARMODS VIM</a></p>\n<p>The site will display your security code.<br/><em>An alternative security code is also generated.</em></p>\n<p><strong>Step 3: Enter security code</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>5F-Computer-electr. </strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Secure access -16</strong>”.</p>\n<p>Enter security code <br/><em>(Use alternative security code if first code does not work)</em></p>\n<p><strong>Step 4: Removing the protection</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>5F-Computer-electr. </strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation -10</strong>”.</p>\n<p><strong>5 – </strong>Select Channel <strong>48</strong> </p>\n<p><em>Set value to <strong>255</strong></em></p>\n<p><strong>Step 5: Restart the MMI</strong></p>\n<p>Simultaneously press MENU + Wheel + Top right button</p>","a8-d4-activate-gearshift-recommendation":"<p><strong>Purpose:</strong> Activates the gearshift recommendation. The gearshift recommendation is then displayed in the lower section of the ODB.   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>“<br/>Then check Bit<strong>“5</strong>“.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/check_aiguille-9b803756.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7102-675f485c.webp\"/></figure>","a8-d4-activate-google-earth-on-mmi-3gp":"<p><strong>Purpose</strong>: to activate the Google Earth map on the MMI 3GP.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> “, then click on ” <strong>Select</strong> “. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Select Byte<strong> 07 </strong>:</p>\n<p>Activate Bit <strong>4</strong> and deactivate Bit <strong>5</strong>, <strong>6</strong> and<strong> 7</strong></p>","a8-d4-activate-mmi-3gp-hidden-menu":"<p><strong>Purpose</strong>: Enables the hidden green menu (green menu, hidden menu, test mode, engineer mode) in the Audi MMI 3G PLUS. </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition and launch the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “<strong>5F – Electrical Information</strong>.”</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Select <em><strong>Channel 6</strong> </em>and set the value to <strong>1</strong></p>\n<p><strong>Facelift Line:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“S12345</strong>“.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong><strong>Developer Mode</strong></strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>From this menu, select “<strong>Enabled</strong>.”</p>\n<p><em><em>No need to restart the MMI.</em></em></p>\n<p><em>To open the Hidden Menu, press MENU + CAR (simultaneously for 6 seconds), or press the CAR button first.</em></p>\n<p><br/><em>For Facelift: <br/>The hidden green menu can be accessed in a different way on newer models/as follows:<br/>NAV/MAP (or CAR) and RADIO<br/>For the red engineering menu, it’s:<br/>NAV/MAP (or CAR) and MEDIA<br/><strong>Note:</strong> First press NAV/MAP (or CAR), then press the second button (MEDIA/RADIO). Hold both buttons down for about five seconds, then release them. The menu should open.  </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/a7_mmi_plus-bb5ba729.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_navigation_plus_mmi3g_hidden_menue-ae4ebd5e.webp\"/></figure>\n<p><strong>Note:</strong> <strong>Never</strong> select the “Bootloader” option!</p>\n<p><strong><a href=\"#/t/access-the-audi-red-engineering-menu\">–&gt; To access the Audi Red Engineering menu</a></strong></p>\n<p><a href=\"#/t/enabling-the-hidden-menu-for-audi-mmi-3g-and-3g\"><strong>–&gt; Enable the hidden MMI 3G/3G+ menu without VCDS or OBDeleven</strong></a></p>","a8-d4-adjust-led-intensity-when-lights-are-on":"<p><strong>Purpose</strong>: Allows you to adjust the brightness of the LEDs (DRL) when the headlights are on.</p>\n<p><em>By default, the LED brightness is set to 9% of maximum power when the lights are on</em>.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “<strong><strong>“09 – Cent. Elect.”</strong></strong>.”</p>\n<p><strong>4</strong> – Click <strong>“Security Access – 16</strong>,” then enter the code <strong>“20113”</strong></p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10”</strong></p>\n<p><strong>6 – </strong> Select<em> <strong>Channel 3</strong>: </em> <br/></p>\n<p><em>Enter a new value between 5 and 100</em><br/><em>(a value less than 5% will generate an error code and a warning on the OBD)</em></p>","a8-d4-audi-sound-system-volume-control":"<p><strong>Purpose</strong>: to adjust the volume of the engine sound (Active Sound System – Soundaktor) inside the car. To mute the sound, use value: 0.   </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><br/> 3 – Click on ” <strong>Select</strong> “, then click on “Select”. <strong><strong><strong>C0 – Aktuator</strong></strong></strong> ” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>6 </strong>– Select Channel <em>:</em><strong>“Actuator volume for motor noise generation</strong>”.</p>\n<p>  Select your sound percentage (between 0 and 100)</p>","a8-d4-automatic-activation-of-electric-handbrake":"<p><strong>Purpose</strong>: automatically activates the electric handbrake when the gear selector is in position “P”.  </p>\n<p><strong>Only for vehicles with automatic gearbox</strong>.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“53-Station brake</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“78713</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”. Then select <strong>“shift P to EPB”</strong> from the drop-down list.</p>\n<p><em>Set value to </em><strong>“<em>active</em></strong></p>","a8-d4-automatic-deactivation-of-electric-handbrake-without-seatbelt":"<p><strong>Purpose:</strong> Allows automatic deactivation of the electric handbrake on start-up without having to fasten the seatbelt.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>53 – Parking Brake</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>61378</strong>“<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – Select <strong>Channel 07</strong></p>\n<p><em>Set the value to<strong> 0</strong></em><br/></p>","a8-d4-automatic-headlight-activation-from-140-km-h":"<p><strong>Purpose: </strong>to automatically switch on the lights when the vehicle is travelling at over 140 km/h. </p>\n<p>(The lights will automatically go out if the vehicle is travelling at less than 60 km/h) </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “2 EPIRBs” module from the drop-down list and click on “Long Coding Helper”:</p>\n<p>Byte <strong>0</strong> Bit <strong>0</strong>: Check “Highway Light Function active above (140kph/90mph)”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_stg09_auswahl-steuergerate-rls-wws-bord-c6f10e6e.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a5_8t_stg09_bordnetz_rls_autobahnlicht_regenl-c0c525c9.webp\"/></figure>","a8-d4-change-mmi-3gp-start-logo":"<p><strong>Purpose</strong>: to change the Splash Screen of the MMI 3G PLUS.  </p>\n<p><em>For a custom logo see tuto: A8 (D4) – MMI 3G/3GP custom start logo</em></p>\n<p><strong>Proceed :</strong> </p>\n<p><strong>To continue, you must first activate the hidden MMI menu (Green Menu).</strong> </p>\n<p><em>To activate the MMI hidden menu (Green Menu) : <a href=\"#/audi/a8-d4/a8-d4-activate-mmi-3gp-hidden-menu\">Activate MMI 3GP Hidden Menu</a></em></p>\n<p><strong>Step 1: Change the start logo in the hidden menu</strong></p>\n<p>Press <strong>CAR + SETUP</strong> for 6 sec to bring up the hidden menu.</p>\n<p>car -&gt; carcodingvehicle -&gt; Select No Of Screen</p>\n<p><em>Select the desired display:</em><br/><em><br/>0 -&gt;  Standard display<br/>1 -&gt;  Standard display<br/>2 -&gt;  A8<br/>3 -&gt;  S8<br/>4 -&gt;  W12<br/>5 -&gt;  A6<br/>6 -&gt;  S6<br/>7 -&gt;  RS6<br/>8 -&gt;  A6 allroad<br/>9 -&gt;  A7<br/>10 -&gt;  S7<br/>11 -&gt;  RS7<br/>12 -&gt;  A1<br/>13 -&gt;  S1<br/>14 -&gt;  Q3<br/>15 -&gt;  A4<br/>16 -&gt;  A4 allroad<br/>17 -&gt;  S4<br/>18 -&gt;  RS4<br/>19 -&gt;  A5<br/>20 -&gt;  S5<br/>21 -&gt;  RS5<br/>22 -&gt;  Q5<br/>23 -&gt;  Q5 Hybrid<br/>24 -&gt;  Q7<br/>25 -&gt;  Q7 Hybrid<br/>26 -&gt;  SQ5<br/>27 -&gt;  Standard display<br/>28 -&gt;  Standard display<br/>29 -&gt;  Standard display</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/splashscreenmmi3gp-6fcb5f6a.webp\"/></figure>\n<p><br/><strong>Step 2: Restart MMI</strong></p>\n<p>Simultaneously press SETUP or MENU (1) + Central knob (2) + Top right knob (3)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/redemarrermmi3g-18d07873.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_S8-1a7397d6.webp\"/></figure>","a8-d4-corner-lights-activation":"<p><strong>Purpose</strong>: to switch on the fog lamp on the side where the steering wheel is turned.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Select Byte <strong>0</strong>, Check Bit <strong>1</strong> and <strong>2</strong></p>\n<p>Select <em>Byte <strong>4</strong>: <br/>Bit <strong>0</strong>: Check “Cornering Light via Fog Lights (depending on Sterring Angle)”.</em></p>","a8-d4-deactivate-open-door-alarm-using-contact":"<p><strong>Purpose:</strong> to deactivate the alarm which is triggered when the door is opened and the contact is in position P.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click<strong>“46 – Comfort Module.”</strong></p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“16017</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>” .</p>\n<p><strong>5</strong> – Select <em><strong>Canal 98</strong>: </em> </p>\n<p><em>Set value to </em><strong><em>“0</em>”</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calculateur-46_Adaptation-Canal_98-b7b82f42.webp\"/></figure>\n<p><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click<strong>“46 – Comfort Module.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>6</strong> – Select <em>Byte <strong>15</strong>: </em> </p>\n<p>Modify Binary value (save original coding)</p>\n<p><br/>With Initial value: 01000111 (47)<br/>New value: 01001111 (4F)</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Calculateur-46_Octet-15_nouvelle_valeur-219f66a3.webp\"/></figure>","a8-d4-deactivate-activate-electric-handbrake-for-rear-brake-pad-change":"<p><strong>Purpose:</strong> to deactivate/activate the electric handbrake in maintenance mode in order to change/replace the rear brake pad/disc linings. (EPB reset / Lining change mode)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><br/>To begin, set the gear lever to P and remove the electric handbrake on the button. Check that there are no faults/errors before starting basic setup.<br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“53 – Parking Brake</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Basic setting – 04</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Start trim change mode.</strong>”<br/><br/><strong>6</strong> – Click on<strong>“Go</strong>”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/plaquettearriere-1024x629-2b32f223.webp\"/></figure>\n<p><br/><br/>A fault message will appear on your ODB indicating “<strong>Parking brake fault</strong>”, but this is normal and should be ignored<br/><br/> 7 – Wait for<strong>“Procedure complete</strong>” to be displayed<br/><br/> 8 – Once finished, return to the program until it closes<br/><br/> 9 – Switch off the vehicle’s ignition, then disconnect the VAG-COM cable<br/><br/><strong>10</strong> – <strong>Change the linings on both sides!</strong><br/><br/><br/></p>\n<p><strong>To reactivate the electric handbrake :</strong><br/><br/><br/><strong>11</strong> – With engine off and ignition switched off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>12</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>13</strong> – Click on<strong>“Select”</strong> then click on<strong>“53 – Parking Brake</strong>”.<br/><br/><strong>14</strong> – Click on<strong>“Basic setting – 04</strong>”.<br/><br/><strong>15</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“End trim change mode.</strong>”<br/><br/><strong>16</strong> – Click on<strong>“Go</strong>”.<br/><br/><strong>17</strong> – Wait for<strong>“Procedure complete</strong>” display</p>","a8-d4-disable-lights-on-warning":"<p><strong>Purpose</strong>: to deactivate the “lights on” warning when the door is open.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>“.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong> “Long Coding Helper”</strong>.</p>\n<p><strong>5</strong> – Select <em>Byte <strong>5 : </strong> </em> </p>\n<p><em>Uncheck Bit<strong> 3</strong></em></p>","a8-d4-disable-nav-phone-warning-messages-when-entering-while-driving":"<p><strong>Purpose</strong>: to suppress navigation and telephone warning messages on the MMI when entering data while driving.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> “, then click on ” <strong>Select</strong> “. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on ” <strong>Adaptation – 10</strong>“.</p>\n<p><strong>5</strong> – Select <em><strong>Channel 2 and 3</strong> </em>then set the value to <strong>250</strong>.</p>","a8-d4-disable-start-stop":"<p><strong>Purpose:</strong> To configure Start and Stop operation. <br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong><br/></p>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>20113</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”<strong>.</strong></p>\n<p><strong>6 –</strong> Choose<strong><em> </em>Channel 34</strong></p>\n<p><em>Enter new value according to desired options</em><br/><em>–<strong>4</strong> Start&amp;Stop disabled by default</em><br/><em><strong>+32</strong> Start&amp;Stop status stored before ignition switch-off</em><br/><em><strong>+64</strong> Reverse button light (on when Start&amp;Stop enabled)</em></p>","a8-d4-display-travel-mode-on-mmi":"<p><strong>Purpose</strong>: to display travel mode on the MMI.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then <strong>“Long Coding Helper”</strong></p>\n<p><strong>5</strong> – Select Byte<strong> 4 </strong>:</p>\n<p>Bit<strong> 6</strong>: Check<em> <strong>“Tourist Mode Adjustable via MMI/Car Menu”.</strong> </em> </p>","a8-d4-electric-tailgate-closure-with-remote-control":"<p><strong>Purpose: </strong>to close the electric tailgate with the remote control.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong>6D – Elect. safe </strong>” .</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“12345</strong>“.</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”. Then select <strong>“Activation using rear lid opening button in remote key-Tap fonction for closing”</strong> from the drop-down list . </p>\n<p><em>Set value to </em><strong>“<em>active</em></strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/7N0-959-107_Module6D_Adaptation_Remote_key-Tap_fun-1faa5c43.webp\"/></figure>","a8-d4-electric-tailgate-lock-with-button":"<p><strong>Purpose </strong>: to close the electric tailgate using the button on the driver’s door.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “Select”.<strong>6D – Elect. safe </strong>” .</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“12345</strong>”.</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”. Then select <strong>“Activation using rear lid remote unlocking switch-Tap function for closing”</strong> from the drop-down list.</p>\n<p><em>Set value to </em><strong>“<em>active</em></strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/7N0-959-107_Module6D_Adaptation_Remote_unlocking_s-5c034a61.webp\"/></figure>","a8-d4-enable-bluetooth-audio-streaming-a2dp-mmi-3gp":"<p><strong>Purpose</strong>: Enables Bluetooth streaming audio on the MMI 3G PLUS, so you can listen to music from your A2DP-compatible audio player.  </p>\n<p><em>ATTENTION: You must have activated the Hidden Menu (<a href=\"#/audi/a8-d4/a8-d4-activate-mmi-3gp-hidden-menu\">Activate hidden menu MMI 3GP</a>)</em> and enabled Bluetooth (either by default or via the “Activate Bluetooth MMI 3GP” tutorial).  </p>\n<p>Press CAR + MENU (for 6s)  </p>\n<p>diagnose -&gt; settings -&gt; ami_aux -&gt; Select <strong>AMI BT [enabled] 1/2</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_bluetooth_ami_bt-8fa46d9c.webp\"/></figure>\n<p>bluetooth -&gt; Check <strong>A2DP Activation</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_bluetooth_ad2p-90e760bc.webp\"/></figure>\n<p>Restart MMI</p>\n<p><em>Press MENU + Wheel + Top Right button.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_bluetooth_ad2p_v2-660aabbb.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_bluetooth_ad2p_v3-6ac58876.webp\"/></figure>","a8-d4-enable-mmi-3gp-cd-dvd-ripping":"<p><strong>Purpose</strong>: Activates CD/DVD extraction in the DVD player. Allows you to import / copy all CD/DVD / SD card content to the MMI 3G PLUS jukebox (hard disk).   </p>\n<p><strong>To continue, you must first activate the hidden MMI menu (Green Menu).</strong></p>\n<p><em><em>To activate the MMI hidden menu (Green Menu) :</em> <a href=\"#/audi/a8-d4/a8-d4-activate-mmi-3gp-hidden-menu\">Activate MMI 3GP hidden menu</a></em></p>\n<p>Press <strong>CAR + SETUP</strong> for 6 sec to bring up the hidden menu.</p>\n<p>diagnose -&gt; settings -&gt; import_multimedia -&gt; Tick <strong>Ripping</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi3g_plus_hidden_menu_cd-ripping-cbf13d3b.webp\"/></figure>\n<p><strong>Restart MMI</strong></p>\n<p><em>Press MENU + Wheel + Top Right button.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/import_ripping_mmi3g_vagcoding-af2ca0fd.webp\"/></figure>","a8-d4-enable-mmi-3gp-wifi-streaming":"<p><strong>Purpose</strong>: Allows you to activate Wifi WLAN (hot spot) on the MMI 3G PLUS and listen to music from your audio player (iOS or Android) using the “Audi Music Stream” app.  </p>\n<p><em>WARNING: You must have activated the Hidden Menu<a href=\"#/audi/a8-d4/a8-d4-activate-mmi-3gp-hidden-menu\">(Activate MMI </a><a href=\"#/audi/a5-8t/a5-8t-facelift-activate-mmi-3gp-hidden-menu\">3GP</a>hidden menu ).</em> </p>\n<p>Press CAR + MENU (for 6s)  </p>\n<p>diagnose -&gt; settings -&gt; wlan_settings -&gt; Check <strong>WLAN activation</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_wlan_settings-469fc399.webp\"/></figure>\n<p>diagnose -&gt; settings -&gt; ami_aux -&gt; Select <strong>AUX [enabled] 1/2</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_ami_bt-fdaa8044.webp\"/></figure>\n<p>Restart MMI</p>\n<p><em>Press MENU + Wheel + Top Right button.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_wlan_settingsv1-1f55118b.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_wlan_settingsv2-9a607dcb.webp\"/></figure>\n<p>After the reboot, new menu items are available in the MMI under Phone and Media.<br/>WLAN parameters can be changed here, e.g. SSID, password, etc.</p>\n<p>The smartphone can now be connected via WLAN and the “Audi Music Stream” application can be launched.<br/>Under Media, you select the WLAN device as the source, e.g. “my iPhone”, and can then use the MMI to navigate the smartphone’s directory structure and select music files for playback.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_music_stream-577x1024-8dc123f4.webp\"/></figure>","a8-d4-headlamp-washer-settings":"<p><strong>Purpose:</strong> to set the delay time before the headlamp washer emerges / the duration of the headlamp washer spray / the number of activations.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1 (Headlamp washer activation time) :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20113</strong>”.</p>\n<p><strong>5</strong> – Click “ <strong>Adaptation – 10</strong>.”</p>\n<p><strong>6</strong> – Select <em><strong>Channel 25</strong>: </em> </p>\n<p><em>Set value to </em><strong><em>“</em>8000”</strong> or value of your choice (default: 2000 ms)  </p>\n<p><strong>Line 2 (Headlamp washer spray duration) :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20113</strong>”.</p>\n<p><strong>5</strong> – Click “ <strong>Adaptation – 10</strong>.”</p>\n<p><strong>6</strong> – Select <em><strong>Channel 06</strong>: </em> </p>\n<p><em>adjust value accordingly (in ms)</em></p>\n<p><strong>Line 3 <strong>(Number of activations before headlamp washer) :</strong></strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20113</strong>”.</p>\n<p><strong>5</strong> – Click “ <strong>Adaptation – 10</strong>.”</p>\n<p><strong>6</strong> – Select <em><strong>Channel 26</strong>: </em><br/><em>adjust the value for the number of times the headlamp washer must be switched on manually before activation.</em></p>","a8-d4-flash-mode-lights-during-emergency-braking":"<p><strong>Purpose</strong>: activates the brake/turn signal lights in flash mode during emergency braking.  </p>\n<p><strong>Procedure </strong>: <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 :</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“46- Central Conv.</strong></p>\n<p>4 – Click on “Coding – 07” then “Long Coding Helper”.</p>\n<p><strong>5</strong> – <em>Select Byte <strong>8</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Emergency Brake Flashing via Turn Lights active” (to activate the turn signals)</em><br/><em>Bit <strong>1: </strong> Check “Emergency Brake Flashing via Brake Lights active” (to activate the brake lights)</em></p>","a8-d4-lock-unlock-confirmation-beeps":"<p><strong>Purpose</strong>: Enables vehicle lock/unlock confirmation with beeps.  </p>\n<p><strong>The vehicle must be equipped with the factory-installed alarm</strong>.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click<strong>“46 – Comfort Module.”</strong></p>\n<p><strong>4</strong> – Click on “ <strong>Code 07.”</strong></p>\n<p><strong>5</strong> – Select <em>Byte <strong>1</strong>: </em> </p>\n<p><em>Bit <strong>2</strong>: Check “Anti-Theft System: Horn Confirmation Active”</em></p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click<strong>“46 – Comfort Module.”</strong></p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>” .</p>\n<p><strong>5</strong> – Select <em><strong>Canal 63</strong>: </em> </p>\n<p><em>Add <strong>04</strong> to the value  </em></p>","a8-d4-lower-passenger-mirror-when-reversing":"<p><strong>Purpose:</strong> automatically lowers the passenger mirror when reversing.  </p>\n<p>The mirror adjustment knob must be in position<strong>“R”</strong> for the passenger mirror to lower automatically.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“52 – Passenger door</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“4</strong>”<br/>Then check Bit<strong>“2</strong>”:<strong>“Reserve Gear Mirror Dipping active</strong>”<br/>and Bit<strong>“3</strong>”:<strong>“Position Memory for Reserve Gear Mirror Dipping active</strong>”.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Golf-7-Abaisser-le-retroviseur-passager-lors-de-la-9710a97c.webp\"/></figure>","a8-d4-lowering-the-pneumatic-chassis":"<p><strong>Purpose:</strong> to lower the air suspension for a lowered style.  </p>\n<p>Select<strong>“Auto</strong>” mode via the MMI (it must not be set to Dynamic, Comfort, etc.). Make sure the car is on level ground. Close the doors. If the doors open during this operation, the procedure will be interrupted. Make sure the car is not in towing or tire-change mode. Eventually set the car to<strong>“Neutral</strong>” and release the handbrake (remember, you’re supposed to be on level ground, so your A6/S6, A7/S7 C7/4G, A8 D4 won’t move).</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program. <strong><strong>34 – Level Control</strong></strong>” .</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”, take note of the 4 values entitled as :</p>\n<p>“<strong>Body height, stops front wheel shell G</strong>”.</p>\n<p>“<strong>Body height, rear wheel shell G</strong>”<strong>stop</strong></p>\n<p>“<strong>Body height, stops front wheel shell D</strong>”.</p>\n<p>“<strong>Body height, rear wheel shell stop D</strong>”.</p>\n<p><strong>6</strong> – Take the values you noted above, and add the desired dimensions in millimetres (mm) to each value, noting them down carefully on a sheet of paper…</p>\n<p>Example of a 15mm front and 11mm rear lowering:</p>\n<ul>\n<li>Front left: <strong>392.80 -&gt; 407.80</strong></li>\n<li>Front right: <strong>388.40 -&gt; 403.40</strong></li>\n<li>Left rear: <strong>391.30 -&gt; 402.30</strong></li>\n<li>Right rear: <strong>385.60 -&gt; 396.60</strong></li>\n</ul>\n<p>Be aware that Audi has a lowering tolerance of 17mm at the front and 13 at the rear, from what I understand. You can go lower if you like, but if you lower it a bit more, it will affect other parts of the system, such as the cameras, adaptive speed, etc., so be careful. </p>\n<p><strong>7</strong> – Press “<strong>RETURN</strong>” Then go to<strong>“04 – Basic settings</strong>”<br/><br/>IMPORTANT: Whatever you do, do not select<strong>“Reset all adaptations</strong>”, as this will not work, and will require a visit to the dealer.<br/><br/> 8 – Select<strong>“Activate trim</strong>”, click<strong>“Go!</strong>”, wait for it to finish (should only take a second or 2, until it says “Not active”) and then press “<strong>Stop</strong>”.</p>\n<p><strong>9</strong> – Select<strong>“Erase trim calibration</strong>”, click on<strong>“Go!</strong>”, wait for it to finish, you’ll see an error message in the central display (ODB) of your meters indicating “<strong>Air Suspension Dysfunction </strong>” with its little yellow car logo (drawings) with a two-way arrow in the center of the car (drawing), don’t worry this is normal, you’ll see in the VCDS writing “Not active” and then press “<strong>Stop</strong>”.</p>\n<p><strong>10</strong> – Select<strong>“Approach reference level</strong>“, click on<strong>“Go!</strong> This step will take about a minute, and your car will rise and fall during the process (you’ll hear whistling). Wait until it finishes, until it says “Not active” and then press ” <strong>Stop</strong> “, then ” <strong>End, Back</strong> “.</p>\n<p><strong>11</strong> – Go to<strong>“10 – Adaptation</strong>” on the previous screen.</p>\n<p><strong>12</strong> – Next, you’ll need to enter the new values you’ve defined with the help of step <strong>4</strong> on your documents for the different heights.</p>\n<p>“<strong>Body height, stops front wheel shell G</strong>”.</p>\n<p>“<strong>Body height, rear wheel shell G</strong>”<strong>stop</strong></p>\n<p>“<strong>Body height, stops front wheel shell D</strong>”.</p>\n<p>“<strong>Body height, rear wheel shell stop D</strong>”.</p>\n<p>Select them, one after the other, to enter the new value you’ve determined, and click on<strong>“Save</strong>”, then repeat the operation for the other three wheel heights.</p>\n<p>Each time you enter a value, you should get a message indicating that it has been accepted.</p>\n<p><strong>13</strong> – When you have completed the changes for all 4 wheels, select<strong>“Back”</strong>, and return to<strong>“04 – Basic settings</strong>” again.</p>\n<p><strong>14</strong> – In the basic settings, select<strong>“Calibrate trim</strong>” and press<strong>“Go!</strong> Wait for “Not active”) and then press ” <strong>Stop</strong> “.</p>\n<p>If you get an error in this step, either you’ve missed a step described above, or something has gone wrong.</p>\n<p><strong>15</strong> – Select<strong>“Activate trim</strong>”, click on<strong>“Go!</strong>”, wait a few seconds until it says “Not active” and then press “<strong>Stop</strong>”, then “<strong>End, Return</strong>”.</p>\n<p><strong>16</strong> – When you’ve finished, go to<strong>“02 – Fault codes</strong>” and clear the error codes.</p>\n<p>Get out of the car and watch, wait a moment, and she’ll lower herself as you wished!</p>\n<p><em>If you’d like to make another adaptation, forget all about the changes you’ve made previously, as they don<strong>‘t add to </strong>the previous ones, and cancel them out completely.</em></p>\n<p><em>For example, you lowered the first time by 5mm on the value 392.80, refer to step 2 of this tutorial and repeat the various steps.</em></p>\n<p><em>This brings your total to 397.80. You want a total reduction of 15mm. You’ll then enter 407.80 the second time, and lower it by a further 10mm on the second modification, bringing you to a total of 5+10=15mm.<br/>I remind you that a “visible” and yet fairly safe lowering value is 17mm at the front and 13mm at the rear, at most. We strongly advise against going any lower.   </em></p>","a8-d4-mmi-3g-3gp-customized-start-logo":"<p><strong>Purpose</strong>: To modify and/or customize the home screen logo (Custom Splash Screen) with a personalized image of the MMI 3G and 3GPLUS. <br/><br/>Start by downloading the script file: <a href=\"https://www.vag-coding.fr/download/MMI_3G_3GP_SplashScreen_VAG-Coding.fr.zip\" rel=\"noopener\" target=\"_blank\">MMI_3G_3GP_SplashScreen_VAG-Coding.en.zip</a></p>\n<p><strong>Proceed </strong>:</p>\n<ul>\n<li>Then extract the file you just downloaded: MMI 3G 3GP SplashScreen VAG-Coding.en.zip</li>\n<li>Go to the “splashscreens” folder and edit the “startup_generic.png” image if you wish. You can edit this image, modify it or import another image, to have your own startup logo (keep the same PNG format and image size 800×480) or an image found in the “samples” folder (copy it into the “splashscreens” folder with the name startup_generic.png. </li>\n<li>Copy the contents of the MMI_3G_3GP_SplashScreen folder to a FAT32-formatted SD card (max. 32GB).</li>\n<li>Start your AUDI and let the MMI boot up, it takes a few seconds.</li>\n<li>Disconnect your smartphone’s Bluetooth if there’s a link between it and the MMI, and remove all your SD cards (SD1 &amp; SD2)…</li>\n<li>Then insert the SD card you have prepared into slot SD1.</li>\n<li>You’ll see green text asking you to turn the large knob on your MMI central console, and the message will disappear.</li>\n<li>Wait a few moments. A new message will appear stating that all has gone well and that your image has been imported successfully. </li>\n<li>Restart the MMI using the button combination that corresponds to your AUDI.<br/>Example: Press SETUP or MENU (1) + Central knob (2) + Top right button (3) at the same time.</li>\n</ul>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/redemarrermmi3g-18d07873.webp\"/></figure>\n<p>If your new start-up screen does not appear when your MMI reboots, go to the green hidden menu<em> (to activate the hidden menu, follow the “Activate MMI 3G or 3GP hidden menu” tutorial).</em></p>\n<p>For <strong>MMI 3GP </strong>: Select in <strong>car </strong>-&gt;<strong> carcodingvehicle </strong>-&gt;<strong> Select n° screen </strong>-&gt;<strong> set cursor to 0</strong>, then restart your MMI.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/splashscreenmmi3gp-6fcb5f6a.webp\"/></figure>\n<p>For <strong>MMI 3G</strong>: <strong>car</strong> -&gt; <strong>carcodingvehicle</strong> -&gt; <strong>configuration line</strong> -&gt; <em><strong>[standard] 2/5</strong> (Standard home screen)</em> then restart your MMI.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_6876-ad94c126.webp\"/></figure>\n<p>Your very own Splash Screen will appear!<br/>Many images are available in the zip file… both the original and modified ones.</p>\n<p><em>A problem?  </em>If the script doesn’t run the first time, try again. You’ve only copied the contents of the MMI_3G_3GP_SplashScreen folder? Do not copy the folder, just its contents!  <br/>For MMI 3G Basic: If your image does not appear or is truncated, resize the image to 400 by 240.</p>\n<hr/>\n<ul><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A1-cca1d214.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A1-quattro-d5c05d6b.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A6-ec35ba13.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A6-allroad-ecfb784b.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A6-Hybrid-8b3bc272.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A6L-da4efe88.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A7-0413e2db.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A8-b82aa2e7.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_A8-Hybrid-bf48c947.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_Q3-f5806bdd.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_Q5-137fb9fc.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_RS6-99c35be3.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_RS7-973708ca.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_RSQ3-82016453.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_RSQ5-4b2a2aa7.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_S1-8fca826d.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_S6-ff017200.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_S6-png_APR-b51955a9.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_S6-APR-5b67cc13.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_S7-1b8e075e.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_S8-1a7397d6.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_Vierge-e6bcc4e4.webp\"/></figure></li><li><figure><img decoding=\"async\" loading=\"lazy\" src=\"img/MMi-SplashScreens_AUDI_W12-9cbddbdf.webp\"/></figure></li></ul><a></a><a></a><a></a>","a8-d4-mmi-3gp-bluetooth-activation":"<p><strong>Purpose</strong>: to activate Bluetooth with an Audi MMI 3G PLUS.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>To continue, you must first activate the hidden MMI menu (Green Menu).</strong></p>\n<p><em>To activate the MMI hidden menu (Green Menu) : <a href=\"#/audi/a8-d4/a8-d4-activate-mmi-3gp-hidden-menu\">Activate MMI 3GP Hidden Menu</a></em></p>\n<p><strong>Step 1: Activate Bluetooth in the hidden menu</strong></p>\n<p>Press <strong>CAR + MENU</strong> for 6 sec to bring up the hidden menu.</p>\n<p>diagnostics  &gt;  settings  &gt;  tel_settings -&gt;  Select <strong>“HFP activation”</strong><br/>diagnose   &gt;  settings  &gt;  tel_settings -&gt;  Select <strong>“BT activation”</strong><br/>diagnostics   &gt;  settings  &gt;  tel_settings -&gt;  Select  <strong>“BT defaut visibility” to [auto] 1/3</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_tel_settings-af0d9718.webp\"/></figure>\n<p>diagnose -&gt; settings -&gt; ami_aux -&gt; Select <strong>AMI BT [enabled] 1/2</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_mmi_3gp_bluetooth_ami_bt-8fa46d9c.webp\"/></figure>\n<p><strong>Step 2: Restart MMI</strong></p>\n<p><em>Press MENU + Wheel + Top Right button.</em></p>\n<p><br/><strong>Step 3: Bluetooth activation with VCDS</strong><br/><br/> 3 – Click on ” <strong>Select”</strong> and then click on ” “.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Choose <em><strong>Channel 17</strong> </em>then set the value to <strong>1</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Module_5F_Adaptation_Channel17-d3fc3a63.webp\"/></figure>","a8-d4-needle-check":"<p><strong>Purpose:</strong> to activate the scanning of the speedometer needles when the car is started. (Needle Sweep)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>”<br/>Then check Bit<strong>“0</strong>”:<strong>“Gauge Test/Needle Sweep active</strong>”.<br/></p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/check_aiguille-9b803756.webp\"/></figure>","a8-d4-oil-temperature-boost-via-lap-timer":"<p><strong>Purpose:</strong> Adds oil temperature and turbo boost to the stopwatch on the ODB screen.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>”<br/>Then check Bit<strong>“3</strong>”:<strong>“Lap Timer active</strong>”.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/check_aiguille-9b803756.webp\"/></figure>\n<p>Standard :</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/boosta81-1024x498-580bc444.webp\"/></figure>\n<p>Enabled (temperature and boost in lap timer) :</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/boosta82-1024x498-763a6ebe.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/boosta83-1024x498-634a9b9a.webp\"/></figure>","a8-d4-opening-closing-windows-with-remote-control":"<p><strong>Purpose</strong>: Enables you to open and close the windows and sunroof using the remote control. </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click<strong>“46 – Comfort Module.”</strong></p>\n<p><strong>4</strong> – Click “<strong>Encoding – 07</strong>,” then click “<strong>Long Coding Helper</strong>.”<br/><br/><strong>5</strong> – Select byte “<strong>2</strong>“<br/>Then check bit “<strong>2</strong>“</p>","a8-d4-rear-daytime-running-lights-drl":"<p><strong>Purpose</strong>: Enables the use of the taillights as daytime running lights (Scandinavian DRL).</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “ <strong>Coding – 07.”</strong></p>\n<p><strong>5</strong> – Select Byte<strong> 2: </strong></p>\n<p>Bit <strong>7</strong>: Check <em>“<strong>Daytime running lights via Tails Lights active</strong>“</em> </p>","a8-d4-remove-electric-handbrake-without-braking":"<p><strong>Purpose:</strong> Allows you to remove the electric handbrake without having fastened your seatbelt, and without having your foot on the brake.  </p>\n<p><strong>This can be dangerous if you have children or pets inside</strong>.  </p>\n<p><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>53 – Parking Brake</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>61378</strong>“<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – Choose <strong>Channel 04</strong></p>\n<p><em>Set the value to<strong> 0</strong></em><br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/pf2-f86aa92b.webp\"/></figure>","a8-d4-reprogram-a-new-battery":"<p><strong>Purpose:</strong> to reprogram / recode the new battery of all its data after replacement.  <br/><br/><br/><strong>Watch out! Depending on your calculator, select 61 or 19</strong> <strong>(CAN or UDS)</strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<h2>61-Batterie Regul. CAN </h2>\n<p>This procedure concerns the replacement of the battery in vehicles using a separate battery management control module.<br/>Address 61: Regul Battery. Labels: 4F0-910-181.lbl Reference SW: 4F0 910 181 E HW: 4F0 915 181 A Component: ENERGIEMANAGER H12 0490 Subsystem 1 – Part No: 000 915 105 C Component: von VA0 2502160103 Coding: 303030393135313035432056413032353032313630313033 Shop N °: WSC 54332 321 22222 </p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“61 – Battery Regul. </strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose the <strong>battery (slave) classified n°1</strong><br/><br/><strong>6</strong> – In<strong>“Coding battery</strong>” :  </p>\n<ul>\n<li>Enter the new Battery Part number (10 or 11 digits).</li>\n<li>Enter the new battery serial number (10 digits).</li>\n<li>Select the new battery supplier.</li>\n</ul>\n<p>[OK]<br/>[! Do – it]<br/>[Close Controller, Go Back – 06]</p>\n<p>Your new battery should now be coded, and the battery control module should be aware of the new battery.</p>\n<hr/>\n<h2>19-CAN Gateway using CAN</h2>\n<p>This procedure concerns battery replacement in vehicles using a battery management control module which is a slave / subsystem of the CAN gateway.Address 19: CAN Gateway (J533) Labels: 8T0-907-468.clb Reference SW: 8T0 907 468 Q HW: 8T0 907 468 L Component: GW-EBM 5CAN-M H10 0095 Subsystem 1 – Part No SW: 8K0 915 181 B HW: 8K0 915 181 B Component: J367-BDM H04 0150</p>\n<p>Installation of a new battery requires use of the [Long Adaptation-0A function] under the 19-CAN-Gateway control module. . Follow the on-screen instructions to enter the part number, supplier, serial number and any long new value.</p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“19 – <strong>Gateway </strong>CAN</strong>”.<br/><br/> 4 – Click on<strong>“Long Adaptation-0A</strong>”.</p>\n<p><strong>5 </strong>– Select <strong>Channel 04</strong></p>\n<p>VCED will populate instructions in the form of a pop-up balloon with formatting. For example:Format: nnnnnnnnnnn XXX zzzzzzzzzz N = battery part number (11 digits) X = battery supplier (3 digits) Z = battery serial number (10 digits) </p>\n<p>[Add to log] Saving the original value in a log is strongly recommended.<br/>Enter the New Battery details in the new field value.</p>\n<ul>\n<li>Note, the new value must be 26 (alpha numeric) characters in total, including spaces! If in doubt, check the logbook for the original battery formatting details. </li>\n</ul>\n<p>[Test]<br/>[Save]<br/>The value has been accepted by the controller the new battery coding is complete<br/>[Done, Back]<br/>[Close Controller, Go Back – 06]</p>\n<hr/>\n<h2>19-CAN Gateway help (UDS / ODX)</h2>\n<p>This procedure concerns battery replacement in vehicles using a battery management control module which is a slave / subsystem of the CAN gateway.Address 19: CAN Gateway (J533) Labels: None Reference SW: 4G0 907 468 E HW: 4G0 907 468 A Component: J533 – Gateway H08 0213 ASAM Dataset: EV_GatewUDS 001025 Battery Monitoring Control Module: Subsystem 1 – Part No SW: 8×0 915 181 HW: 8×0 915 181 Component: J367-BDM H07 0140</p>\n<p>Installing a new battery requires the use of the [Adaptation-10 function] under the 19-CAN-Gateway control module. Use the drop-down menus to enter the part number, vendor, and serial number information located on the new battery. </p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.<br/><br/><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Adaptation batterie-Capacité nominal de la batterie</strong>”.<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu, but towards the bottom<br/>of the page.<br/>On this menu, choose a nominal value indicated on your battery, e.g.<strong>“70Ah</strong>”.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Adaptation batterie-Fabriquant de batterie</strong>”.<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose the corresponding brand:<br/>Ex: In the case of the VARTA E39, choose<strong>“VAO</strong>”.</p>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Adaptation batterie-Numéro de série de la batterie</strong>”.<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, enter the corresponding serial number:<br/>Warning, insert only the <strong>last 10 digits</strong> of the serial number.</p>\n<p>The value has been accepted by the controller the new battery coding is complete<br/>[Done, Back]<br/>[Close Controller, Go Back – 06]</p>\n<hr/>\n<p><strong>Battery</strong></p>\n<p>The vehicle’s battery is housed in the engine compartment and protected by a battery tray. Battery size and design depend on engine version, equipment and national variant. Standard, EFB and AGM batteries are used.<br/>Vehicles with petrol engines and start/stop systems are fitted with EFB batteries, while vehicles with diesel engines and start/stop systems are fitted with AGM batteries.   Vehicles with stationary chauﬀage generally have an AGM battery.</p>\n<p><strong>EFB</strong></p>\n<p>An EFB (Enhanced Flooded Battery) is a reinforced wet battery. The positive plate inside the battery is coated with an additional polyester canvas. This gives the battery’s active mass additional support on the plate. The alternating cycle resistance of these batteries is superior to that of standard batteries. During charging, the EFB battery is treated like a standard battery.</p>\n<p><strong>AGM battery</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/batterie-agm-f4b81a74.webp\"/></figure>\n<p>In AGM batteries (short for Absorbent Glass Mat), the battery’s electrolyte is retained in a micro-porous glass mat. An AGM battery is not only even more resistant to alternating cycles than an EFB battery, but also watertight. When charging, follow the charger’s operating instructions and select the AGM battery program if necessary.</p>\n<p>In the case of AGM batteries, the automotive battery electrolyte is retained in a micro-porous glass mat. In addition to<br/>increased resistance to alternating cycles, an AGM battery is characterized by its good sealing properties. Waterproofing is of crucial importance<br/>, especially when the battery is installed in<br/>the passenger compartment. When charging, please follow the charger’s operating instructions and select the program for<br/>AGM battery, if applicable.</p>\n<p>Below we see the battery brand, serial number and manufacturer.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/batterie-124711ff.webp\"/></figure>","a8-d4-speed-of-radar-deactivation-or-reversing-camera":"<p><strong>Purpose </strong>: Selects the speed at which radar and/or reversing camera are deactivated.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>10 – Assistance stationn</strong>”.  <br/><br/><strong>4 – </strong>Click on <strong>“Adaptation – 10”</strong> </p>\n<p>5 – Select<strong> Channel 23 or 233 from </strong>the list of values</p>\n<p><strong>6 –</strong> Choose a value between <strong>0 and 20 km/h</strong></p>","a8-d4-speed-limit-display":"<p><strong>Purpose:</strong> to unlock/activate the speed limit display (via MMI navigation) is shown in the instrument cluster (IA / dashboard).  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“5</strong>”<br/>Then check Bit<strong>“2</strong>”.</p>","a8-d4-suppress-belt-alarm":"<p><strong>Purpose</strong>: To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select</strong>”, then click on “<strong>17 – Instruments</strong>”. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then<strong>“Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select byte <strong>0</strong>:<br/>Bit <strong>2-4</strong>: select <strong>“Seat Belt Warning inactive”</strong> from the drop-down list.</p>\n<p><strong><em>OR</em></strong></p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose <strong>“Deactivate</strong> <strong>Seat belt warning”</strong> / <strong>“</strong> <strong>Désactiver l’avertissement de ceinture”.</strong> <br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, at the bottom<br/>of the page.<br/>On this menu, select<strong>“Oui</strong>” /<strong>“Yes”</strong> and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8U0_920_940_Module17_Adaptation_desactivate_seat_b-77d3b532.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","a8-d4-activate-daytime-running-lights-drl-on-mmi":"<p><strong>Purpose</strong>: to activate/deactivate the daytime running lights (DRL) on the MMI.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p>4 – Click on “Coding – 07” then “Long Coding Helper”.</p>\n<p><strong>5</strong> – Select Byte<strong> 3 </strong>:</p>\n<p>Bit<strong> 0 </strong>: Check<em> <strong>“Daytime Running Lights Adjustable via MMI/Car Menu”.</strong> </em> </p>","a8-d4-us-turn-signal":"<p><strong>Purpose</strong>: to activate US nightlights with turn signals.  </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong></strong> 2 – Turn on the ignition, then launch the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click <strong>“Select</strong>,” then click “<strong><strong>09 – Power Control Unit</strong></strong> .”</p>\n<p><strong>4</strong> – Click on “ <strong>Coding – 07</strong>.”</p>\n<p><strong>5</strong> – Select Byte<strong> 10: </strong></p>\n<p>Bit <strong>0</strong>: Check <em>“</em> <strong>Turn signal active as side marker</strong> “</p>"};
